    "why": "PHASE 1 VERDICT: KEEP as a Canada fallback application — research fit is the best on the list, but there is NO guaranteed stipend (tuition ~$10,082/yr minus $3,200 ITA; summer RA up to $12,000; TA $37.53/h), GMAT/GRE mandatory, deadline 31 Dec 2026, application fee waived for Bangladesh. Earlier note: ⭐ STRONGEST OVERALL PACKAGE AFTER FRANÇOIS. Her research is published in the Journal of Financial Economics and the Review of Financial Studies — two top-3 journals. Her central topic is MONETARY POLICY TRANSMISSION through financial intermediation, which is exactly the mechanism Bangladesh is living through. She is an assistant professor, historically the highest-response category, and she won a best-paper award for the shadow-bank transmission work.",
    "contribution": "The crowding-out paper distinguishes bank-lending from bond-market crowding out in an emerging market. Bangladesh supplies a discrete, dated regime change: since June 2024 the central bank stopped absorbing unsold sovereign debt, shifting government borrowing onto commercial banks. Banks flooded the auctions, the 91-day bill collapsed to 8.28%, and private credit growth fell to 4.47% — the weakest since 1993. You can measure the crowding-out differential ACROSS that institutional break using auction data plus bank balance sheets. Very few researchers get a clean break of that kind. Her shadow-bank transmission work is ALSO relevant: Bangladesh Bank's exit from primary absorption is a change in the intermediation chain.",
